export interface VoucherRecord {
  usageCount: number
  lastUsedAt: number
}

export class VoucherUsageCoordinator {
  private store: VoucherStore = new VoucherStore()

  async recordSuccessfulUse(record: VoucherRecord): Promise<void> {
    record.usageCount += 1
    record.lastUsedAt = Date.now()
    await this.store.save(record)
  }
}

